const LearnSet *learnset_get(uint16_t pokemon_id)
{
    for (unsigned i = 0; i < LEARNSET_COUNT; i++) {
        if (kLearnSets[i].pid == pokemon_id) return &kLearnSets[i].set;
    }
    return NULL;
}
